window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e99e4fe93523eb3c"]={"versions": [{"id": "FIG-e99e4fe93523eb3c", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Verhaltensdiagramm / Kontrollfluss).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des generischen algorithmischen Teilschritts „Compute offset“ innerhalb des AUTOSAR E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der Vereinheitlichung der E2E-Profilimplementierungen (Profile <code>XX</code>, z. B. P01, P02, P04, P05 etc.) in Classic Platform (E2E Library) und Adaptive Platform (ara::com E2E Protection). Definiert die synchrone Transformation des konfiguratorischen Bit-Offsets in einen für PDU-Array-Indexierungen nutzbaren Byte-Offset.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Aktivitäten (Subaktivitäts-Referenzen mit Rake-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXProtect()</code>: Senderseitige Absicherung der Nutzdaten (CRC-, Counter-, Header-Injektion).\n</li><li><code>E2E_PXXSourceCheck()</code> / <code>E2E_PXXCheck()</code>: Empfängerseitige Daten- und Header-Prüfung.\n</li><li><code>E2E_PXXForward()</code>: Validierung und Weiterschaltung geschützter Daten über Gateways.\n</li><li><em>Hinweis-Knoten:</em> Der Platzhalter <code>XX</code> repräsentiert das jeweilige konkrete Profil; modulspezifische Ausprägungen werden auf Profilebene fixiert.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code>: Konfigurationsparameter aus <code>E2E_PXXConfigType</code>. Einheit: <strong>[Bit]</strong>.\n</li><li><code>Offset</code>: Lokale Variable vom Datentyp <code>uint16</code>. Einheit: <strong>[Byte]</strong>.\n</li></ul>\n</li><li><strong>Diagramm-Elemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (Startknoten)\n</li><li><em>Action Node</em> (<code>Offset = Config-&gt;Offset / 8</code>)\n</li><li><em>Activity Final Node</em> (Endknoten)\n</li><li><em>Comment / Note</em>: Spezifikation des Ziel-Datentyps (<code>uint16</code>) und der physikalischen Einheit (<code>[byte]</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Eintritt:</strong> Unmittelbar nach Abschluss des vorgeschalteten Validierungsschritts (z. B. <code>Verify inputs of the protect/check function</code> gemäß <code>PRS_E2E_01210</code>).\n</li><li><strong>Kalkulation:</strong> \n $$\\text{Offset} = \\frac{\\text{Config}\\rightarrow\\text{Offset}}{8}$$\n Synchrone Ganzzahldivision bzw. Bit-Shift (<code>&gt;&gt; 3</code>) des konfigurierten Bit-Werts.\n</li><li><strong>Abschluss:</strong> Direkter Übergang in den Activity Final Node; der berechnete <code>uint16</code>-Byte-Offset steht den nachfolgenden Schritten (wie Serialisierung, In-Place-Header-Positionierung, CRC-Berechnung) als lokaler Offset-Zeiger im PDU-Puffer zur Verfügung.\n</li><li><strong>Fehlerpfade / Callbacks:</strong> Keine Verzweigungen, Guard Conditions oder Det/Dem-Meldungen in diesem Schritt (vollständig deterministischer linearer Ablauf).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- &amp; Datenvertrag:</strong>\n<ul class=\"fig-list\"><li>Konfigurationsgeneratoren (ARXML-Parameter <code>E2EProfile&lt;XX&gt;Offset</code>) übergeben den Offset spezifikationsgemäß in <strong>Bits</strong>, um Bit-genaue Payload-Starts im AUTOSAR-Metamodell abzubilden.\n</li><li>Die C/C++-Implementierung muss intern einen <code>uint16</code> vorhalten, um PDU-Längen bis mindestens 65.535 Bytes (z. B. Ethernet / Large PDUs in Profil 04/07/22) adressieren zu können.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li>Der Schritt setzt zwingend voraus, dass <code>Config-&gt;Offset % 8 == 0</code> gilt (Byte-Aligned Offset). Die Einhaltung muss bereits im vorgelagerten Generator-Check oder im Schritt <code>Verify inputs</code> geprüft und mit <code>E2E_E_INPUTERR_WRONG</code> abgefangen worden sein.\n</li></ul>\n</li><li><strong>Optimierung für Embedded-Targets:</strong>\n<ul class=\"fig-list\"><li>Auf Fixed-Point/Mikrocontrollern ohne Hardware-Divider ist die Operation als arithmetischer/logischer Shift (<code>Config-&gt;Offset &gt;&gt; 3u</code>) ohne Rundungsverlust zu realisieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2639e48fb697af68", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Verhaltensdiagramm / Kontrollfluss).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des generischen algorithmischen Teilschritts „Compute offset“ innerhalb des AUTOSAR E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der Vereinheitlichung der E2E-Profilimplementierungen (Profile <code>XX</code>, z. B. P01, P02, P04, P05 etc.) in Classic Platform (E2E Library) und Adaptive Platform (ara::com E2E Protection). Definiert die synchrone Transformation des konfiguratorischen Bit-Offsets in einen für PDU-Array-Indexierungen nutzbaren Byte-Offset.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Aktivitäten (Subaktivitäts-Referenzen mit Rake-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXProtect()</code>: Senderseitige Absicherung der Nutzdaten (CRC-, Counter-, Header-Injektion).\n</li><li><code>E2E_PXXSourceCheck()</code> / <code>E2E_PXXCheck()</code>: Empfängerseitige Daten- und Header-Prüfung.\n</li><li><code>E2E_PXXForward()</code>: Validierung und Weiterschaltung geschützter Daten über Gateways.\n</li><li><em>Hinweis-Knoten:</em> Der Platzhalter <code>XX</code> repräsentiert das jeweilige konkrete Profil; modulspezifische Ausprägungen werden auf Profilebene fixiert.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code>: Konfigurationsparameter aus <code>E2E_PXXConfigType</code>. Einheit: <strong>[Bit]</strong>.\n</li><li><code>Offset</code>: Lokale Variable vom Datentyp <code>uint16</code>. Einheit: <strong>[Byte]</strong>.\n</li></ul>\n</li><li><strong>Diagramm-Elemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (Startknoten)\n</li><li><em>Action Node</em> (<code>Offset = Config-&gt;Offset / 8</code>)\n</li><li><em>Activity Final Node</em> (Endknoten)\n</li><li><em>Comment / Note</em>: Spezifikation des Ziel-Datentyps (<code>uint16</code>) und der physikalischen Einheit (<code>[byte]</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Eintritt:</strong> Unmittelbar nach Abschluss des vorgeschalteten Validierungsschritts (z. B. <code>Verify inputs of the protect/check function</code> gemäß <code>PRS_E2E_01210</code>).\n</li><li><strong>Kalkulation:</strong> \n $$\\text{Offset} = \\frac{\\text{Config}\\rightarrow\\text{Offset}}{8}$$\n Synchrone Ganzzahldivision bzw. Bit-Shift (<code>&gt;&gt; 3</code>) des konfigurierten Bit-Werts.\n</li><li><strong>Abschluss:</strong> Direkter Übergang in den Activity Final Node; der berechnete <code>uint16</code>-Byte-Offset steht den nachfolgenden Schritten (wie Serialisierung, In-Place-Header-Positionierung, CRC-Berechnung) als lokaler Offset-Zeiger im PDU-Puffer zur Verfügung.\n</li><li><strong>Fehlerpfade / Callbacks:</strong> Keine Verzweigungen, Guard Conditions oder Det/Dem-Meldungen in diesem Schritt (vollständig deterministischer linearer Ablauf).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- &amp; Datenvertrag:</strong>\n<ul class=\"fig-list\"><li>Konfigurationsgeneratoren (ARXML-Parameter <code>E2EProfile&lt;XX&gt;Offset</code>) übergeben den Offset spezifikationsgemäß in <strong>Bits</strong>, um Bit-genaue Payload-Starts im AUTOSAR-Metamodell abzubilden.\n</li><li>Die C/C++-Implementierung muss intern einen <code>uint16</code> vorhalten, um PDU-Längen bis mindestens 65.535 Bytes (z. B. Ethernet / Large PDUs in Profil 04/07/22) adressieren zu können.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li>Der Schritt setzt zwingend voraus, dass <code>Config-&gt;Offset % 8 == 0</code> gilt (Byte-Aligned Offset). Die Einhaltung muss bereits im vorgelagerten Generator-Check oder im Schritt <code>Verify inputs</code> geprüft und mit <code>E2E_E_INPUTERR_WRONG</code> abgefangen worden sein.\n</li></ul>\n</li><li><strong>Optimierung für Embedded-Targets:</strong>\n<ul class=\"fig-list\"><li>Auf Fixed-Point/Mikrocontrollern ohne Hardware-Divider ist die Operation als arithmetischer/logischer Shift (<code>Config-&gt;Offset &gt;&gt; 3u</code>) ohne Rundungsverlust zu realisieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7f16ffe50960f512", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Verhaltensdiagramm / Kontrollfluss).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des generischen algorithmischen Teilschritts „Compute offset“ innerhalb des AUTOSAR E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der Vereinheitlichung der E2E-Profilimplementierungen (Profile <code>XX</code>, z. B. P01, P02, P04, P05 etc.) in Classic Platform (E2E Library) und Adaptive Platform (ara::com E2E Protection). Definiert die synchrone Transformation des konfiguratorischen Bit-Offsets in einen für PDU-Array-Indexierungen nutzbaren Byte-Offset.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Aktivitäten (Subaktivitäts-Referenzen mit Rake-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXProtect()</code>: Senderseitige Absicherung der Nutzdaten (CRC-, Counter-, Header-Injektion).\n</li><li><code>E2E_PXXSourceCheck()</code> / <code>E2E_PXXCheck()</code>: Empfängerseitige Daten- und Header-Prüfung.\n</li><li><code>E2E_PXXForward()</code>: Validierung und Weiterschaltung geschützter Daten über Gateways.\n</li><li><em>Hinweis-Knoten:</em> Der Platzhalter <code>XX</code> repräsentiert das jeweilige konkrete Profil; modulspezifische Ausprägungen werden auf Profilebene fixiert.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code>: Konfigurationsparameter aus <code>E2E_PXXConfigType</code>. Einheit: <strong>[Bit]</strong>.\n</li><li><code>Offset</code>: Lokale Variable vom Datentyp <code>uint16</code>. Einheit: <strong>[Byte]</strong>.\n</li></ul>\n</li><li><strong>Diagramm-Elemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (Startknoten)\n</li><li><em>Action Node</em> (<code>Offset = Config-&gt;Offset / 8</code>)\n</li><li><em>Activity Final Node</em> (Endknoten)\n</li><li><em>Comment / Note</em>: Spezifikation des Ziel-Datentyps (<code>uint16</code>) und der physikalischen Einheit (<code>[byte]</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Eintritt:</strong> Unmittelbar nach Abschluss des vorgeschalteten Validierungsschritts (z. B. <code>Verify inputs of the protect/check function</code> gemäß <code>PRS_E2E_01210</code>).\n</li><li><strong>Kalkulation:</strong> \n $$\\text{Offset} = \\frac{\\text{Config}\\rightarrow\\text{Offset}}{8}$$\n Synchrone Ganzzahldivision bzw. Bit-Shift (<code>&gt;&gt; 3</code>) des konfigurierten Bit-Werts.\n</li><li><strong>Abschluss:</strong> Direkter Übergang in den Activity Final Node; der berechnete <code>uint16</code>-Byte-Offset steht den nachfolgenden Schritten (wie Serialisierung, In-Place-Header-Positionierung, CRC-Berechnung) als lokaler Offset-Zeiger im PDU-Puffer zur Verfügung.\n</li><li><strong>Fehlerpfade / Callbacks:</strong> Keine Verzweigungen, Guard Conditions oder Det/Dem-Meldungen in diesem Schritt (vollständig deterministischer linearer Ablauf).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- &amp; Datenvertrag:</strong>\n<ul class=\"fig-list\"><li>Konfigurationsgeneratoren (ARXML-Parameter <code>E2EProfile&lt;XX&gt;Offset</code>) übergeben den Offset spezifikationsgemäß in <strong>Bits</strong>, um Bit-genaue Payload-Starts im AUTOSAR-Metamodell abzubilden.\n</li><li>Die C/C++-Implementierung muss intern einen <code>uint16</code> vorhalten, um PDU-Längen bis mindestens 65.535 Bytes (z. B. Ethernet / Large PDUs in Profil 04/07/22) adressieren zu können.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li>Der Schritt setzt zwingend voraus, dass <code>Config-&gt;Offset % 8 == 0</code> gilt (Byte-Aligned Offset). Die Einhaltung muss bereits im vorgelagerten Generator-Check oder im Schritt <code>Verify inputs</code> geprüft und mit <code>E2E_E_INPUTERR_WRONG</code> abgefangen worden sein.\n</li></ul>\n</li><li><strong>Optimierung für Embedded-Targets:</strong>\n<ul class=\"fig-list\"><li>Auf Fixed-Point/Mikrocontrollern ohne Hardware-Divider ist die Operation als arithmetischer/logischer Shift (<code>Config-&gt;Offset &gt;&gt; 3u</code>) ohne Rundungsverlust zu realisieren.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-e99e4fe93523eb3c", "to": "FIG-2639e48fb697af68", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Am oberen Bildrand wurden überstehende Textfragmente aus dem Dokumenten-Fließtext (u. a. „...ave as shown in Figure 6.4...]...“) entfernt.\n</li><li>Im linken Kasten für <code>E2E_PXXSourceCheck()</code> wurde das Klammerpaar <code>()</code> auf eine zweite Zeile unterhalb von <code>E2E_PXXSourceCheck</code> umgebrochen.\n</li></ul>"}, {"from": "FIG-2639e48fb697af68", "to": "FIG-7f16ffe50960f512", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
